blobs.main:
from fastapi import FastAPI

app = FastAPI()


@app.get('/health')
def health():
    return {'ok': True}

blobs.custom_project_wide:
resource "google_secret_manager_secret" "creds" {
  secret_id = "${var.product_id}-creds"
  replication {
    auto {}
  }
}

resource "google_project_iam_member" "workload_secret_accessor" {
  project = var.project_id
  role    = "roles/secretmanager.secretAccessor"
  member  = "serviceAccount:${module.foundation.workload_sa_email}"
}

blobs.custom_scoped:
resource "google_secret_manager_secret" "creds" {
  secret_id = "${var.product_id}-creds"
  replication {
    auto {}
  }
}

resource "google_secret_manager_secret_iam_member" "workload_secret_accessor" {
  secret_id = google_secret_manager_secret.creds.secret_id
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${module.foundation.workload_sa_email}"
}
